"""W4 declared grid: signal,pairs,hl_grid,prior,density binary cross (32), 2 hyperparameters; four catalog ablations at best. TRAIN labels only except S5 dev episode-OOF soft-q. No audit fitting/tuning. Smoke24 before full;600s process bound. S1 iteration caps20/80 and S8 caps35/200 were independently completed; defaults20/200 select best dev. Set W4_HIST_ITER or W4_MLP_ITER to reproduce each cap."""
import os,sys,json,time,itertools,warnings
from pathlib import Path
import numpy as np
from sklearn.ensemble import HistGradientBoostingRegressor
from sklearn.linear_model import Ridge,LogisticRegression
from sklearn.neural_network import MLPRegressor
from sklearn.preprocessing import StandardScaler
from sklearn.pipeline import make_pipeline
from sklearn.exceptions import ConvergenceWarning
from harness import evaluate,diff_ci,blend_gain,to_csv,read_pred_csv,write_result,audit_episodes,smoke_split
warnings.filterwarnings('ignore',category=ConvergenceWarning)
warnings.filterwarnings('ignore',message='X does not have valid feature names.*')
ns={}
if True:
 exec(json.loads(Path('results/W3W4_COMMON.json').read_text())['source'],ns)
 D=ns['load_features']();v=ns['load_validation']();B=read_pred_csv('preds/B3_validation.csv',v)
CONFIGS=[dict(zip(('signal','pairs','hl_grid','prior','density'),x)) for x in itertools.product((0,1),repeat=5)]
PAY=np.array([0,1,2,5,20]);SEED=20261107
HIST_ITER=int(os.environ.get('W4_HIST_ITER','20'));MLP_ITER=int(os.environ.get('W4_MLP_ITER','200'));LAST_FIT={}

def normalize(a):
 a=np.maximum(a,1e-6);return a/a.sum(1,keepdims=True)
def target(block):return (block['outcome'][:,None]==PAY).astype(float)
def features(block,cfg,ablation=None):
 x=np.nan_to_num(ns['cell_X'](block,cfg),nan=0,posinf=0,neginf=0)
 if ablation:
  # Shared names identify catalogue groups; appended base columns always retained.
  names=ns['cell_names'](block,cfg)
  pats={'lags':('lag','pair'),'frequency':('freq','ess','obs','density'), 'drift':('jsd','tv','cusum','drift','l2'),'context':('peer','episode','loo','moment','since')}
  keep=[not any(p in n.lower() for p in pats[ablation]) for n in names[:x.shape[1]]]
  if len(keep)==x.shape[1] and any(keep):x=x[:,keep]
 return x

def base(block,idx):return block['base'][idx]
def fit_residual(x,y,xv,kind,h):
 global LAST_FIT
 if kind=='optional':
  sys.path.insert(0,'/private/tmp/house-edge-w3w4-optional')
  family,depth=h.split('_');depth=int(depth)
  if family=='cat':
   from catboost import CatBoostRegressor
   m=CatBoostRegressor(iterations=25,depth=depth,loss_function='MultiRMSE',thread_count=1,random_seed=SEED,verbose=False,allow_writing_files=False);m.fit(x,y);return m.predict(xv)
  from lightgbm import LGBMRegressor
  out=[]
  for j in range(5):
   m=LGBMRegressor(n_estimators=25,num_leaves=depth,n_jobs=1,verbosity=-1,random_state=SEED,deterministic=True,force_col_wise=True);m.fit(x,y[:,j]);out.append(m.predict(xv))
  return np.array(out).T
 if kind=='hist':
  out=[]
  for j in range(5):
   m=HistGradientBoostingRegressor(max_iter=HIST_ITER,max_leaf_nodes=h,l2_regularization=10,min_samples_leaf=32,early_stopping=False,random_state=SEED)
   m.fit(x,y[:,j]);out.append(m.predict(xv))
  return np.array(out).T
 if kind=='mlp':m=make_pipeline(StandardScaler(),MLPRegressor(hidden_layer_sizes=(h,),max_iter=MLP_ITER,batch_size=128,alpha=1,random_state=SEED,early_stopping=False,shuffle=False,tol=1e-5))
 else:m=make_pipeline(StandardScaler(),Ridge(alpha=h))
 m.fit(x,y)
 LAST_FIT={'kind':kind}
 if kind=='mlp':LAST_FIT.update(n_iter=int(m[-1].n_iter_),loss=float(m[-1].loss_),loss_curve=[float(z) for z in m[-1].loss_curve_],configured_max_iter=MLP_ITER)
 return m.predict(xv)

def predict(mid,idx,h,ablation=None):
 cfg=CONFIGS[idx];tr=D['roll'] if mid in ('S4','S6') else D['tr'];va=D['va']
 x=features(tr,cfg,ablation);xv=features(va,cfg,ablation);bt=base(tr,idx);bv=base(va,idx)
 if mid=='S6':
  keep=np.asarray(tr['future_valid'],bool);x=x[keep];bt=bt[keep]
  tr={k:(a[keep] if isinstance(a,np.ndarray) and len(a)==len(keep) else a) for k,a in tr.items()}
 if mid=='S7':
  m=make_pipeline(StandardScaler(),LogisticRegression(C=h,max_iter=120,solver='lbfgs',random_state=SEED))
  m.fit(x,tr['outcome']);p=m.predict_proba(xv);out=np.full((len(xv),5),1e-6)
  for j,c in enumerate(m[-1].classes_):out[:,list(PAY).index(c)]=p[:,j]
  return normalize(out)
 if mid=='S3':
  gate=make_pipeline(StandardScaler(),LogisticRegression(C=h,max_iter=100,random_state=SEED));gate.fit(x,tr['condition'])
  weights=gate.predict_proba(xv);out=np.zeros_like(bv)
  for j,c in enumerate(gate[-1].classes_):
   keep=tr['condition']==c
   out+=weights[:,j,None]*normalize(bv+fit_residual(x[keep],target(tr)[keep]-bt[keep],xv,'ridge',100))
  return normalize(out)
 if mid=='S5':
  # Every scored dev episode is predicted by a fit excluding its whole episode.
  import hashlib
  audit=audit_episodes(v);dev=np.array([e not in audit for e in v.episode]);assert not np.any(dev & np.isin(v.episode,list(audit)))
  eps=sorted(set(v.episode[dev]),key=lambda e:hashlib.sha256(('w4-s5|'+e).encode()).hexdigest());fold={e:i%6 for i,e in enumerate(eps)}
  out=bv.copy();xx=features(va,cfg,ablation)
  for f in range(6):
   ti=np.array([dev[i] and fold.get(e)!=f for i,e in enumerate(v.episode)]);te=np.array([dev[i] and fold.get(e)==f for i,e in enumerate(v.episode)])
   assert not set(v.episode[ti])&set(v.episode[te]);assert not set(v.episode[ti])&audit
   out[te]=normalize(bv[te]+fit_residual(xx[ti],v.truth[ti]-bv[ti],xx[te],'ridge',h))
  ai=~dev
  out[ai]=normalize(bv[ai]+fit_residual(xx[dev],v.truth[dev]-bv[dev],xx[ai],'ridge',h))
  return out
 y=tr['future'] if mid=='S6' else target(tr)
 kind='optional' if mid=='S2' else 'hist' if mid=='S1' else 'mlp' if mid=='S8' else 'ridge'
 return normalize(bv+fit_residual(x,y-bt,xv,kind,h))

HYPERS={'S2':['cat_3','cat_5','light_7','light_15'],'S1':[7,15],'S3':[.1,1.],'S4':[100.,1000.],'S5':[100.,1000.],'S6':[100.,1000.],'S7':[.01,.1],'S8':[8,16]}
def score(p,smoke=False):
 if smoke:
  sv=smoke_split(v);pos={q:i for i,q in enumerate(v.qid)};rows=[pos[q] for q in sv.qid];return evaluate(p[rows],sv,'smoke',bootstrap=0)
 return evaluate(p,v,'dev',bootstrap=0)
def save_unavailable(mid,detail):
 doc={'id':mid,'owner':'codex','description':'CatBoost/LightGBM dependency runtime availability','status':'unavailable','runtime_attempts':detail,'completed_cells':0,'grid':[],'stdlib_only':False,'audit_fitting':False}
 Path('results/'+mid+'.json').write_text(json.dumps(doc,indent=1));Path('reports/'+mid+'.md').write_text(mid+'\nRuntime import attempts: '+json.dumps(detail)+'\nNo packages installed; 0 cells completed.\nNo score or verdict claimed.\n')
def main():
 mid=sys.argv[1];phase=sys.argv[2] if len(sys.argv)>2 else 'full';start=time.monotonic();optional_status={}
 if mid=='S2':
  import importlib
  sys.path.insert(0,'/private/tmp/house-edge-w3w4-optional')
  available=[]
  for mod,prefix in [('catboost','cat_'),('lightgbm','light_')]:
   try:
    mm=importlib.import_module(mod);optional_status[mod]={'available':True,'version':mm.__version__};available.extend([h for h in HYPERS[mid] if h.startswith(prefix)])
   except Exception as err:optional_status[mod]={'available':False,'error':type(err).__name__+': '+str(err)}
  HYPERS[mid]=available
  if not available:save_unavailable(mid,optional_status);return
 if mid=='S2' and phase=='availability':
  sys.path.insert(0,'/private/tmp/house-edge-w3w4-optional')
  import importlib
  detail={}
  for mod in ('catboost','lightgbm'):
   try: m=importlib.import_module(mod);detail[mod]={'available':True,'version':m.__version__}
   except Exception as e:detail[mod]={'available':False,'error':type(e).__name__+': '+str(e)}
  save_unavailable(mid,detail);print(json.dumps(detail));return
 if phase=='smoke':
  p=predict(mid,0,HYPERS[mid][0]);ev=score(p,True);elapsed=time.monotonic()-start
  print(json.dumps({'id':mid,'smoke_points':ev['points'],'seconds':elapsed,'grid_estimate_seconds':elapsed*32*len(HYPERS[mid])}));return
 cells=[];best=None
 for idx,cfg in enumerate(CONFIGS):
  for h in HYPERS[mid]:
   t0=time.monotonic();p=predict(mid,idx,h);ev=score(p);cell={'config':cfg,'config_index':idx,'hyper':h,'points':ev['points'],'condition_ratios':ev['condition_ratios'],'runtime_seconds':time.monotonic()-t0};cells.append(cell)
   if best is None or ev['points']>best[0]:best=(ev['points'],idx,h,p)
   if time.monotonic()-start>480:break
  if time.monotonic()-start>480:break
 pts,idx,h,p=best;abl=[]
 for a in ('lags','frequency','drift','context'):
  if time.monotonic()-start>530:break
  ap=predict(mid,idx,h,a);ae=score(ap);abl.append({'omit':a,'points':ae['points'],'condition_ratios':ae['condition_ratios']})
 # Refit best from fixed seed to verify the actual fitting path determinism.
 p2=predict(mid,idx,h);det=float(np.max(np.abs(p2-p)));assert det<1e-8
 paired=diff_ci(p,B,v,'dev');blend=blend_gain(p,B,v);blend.pop('oof')
 extra={'fitting_metadata':LAST_FIT.copy(),'training_iterations':{'hist':HIST_ITER,'mlp':MLP_ITER},'smoke':json.loads(os.environ.get('W4_SMOKE','{}')),'grid':cells,'completed_cells':len(cells),'declared_cells':128 if mid=='S2' else 64,'optional_runtime_attempts':optional_status,'feature_ablations':abl,'standalone_vs_B3':paired,'episode_oof_blend':blend,'selection_caveat':'Global hyperparameter selection on dev before episode-OOF blend is optimistic; S5 fold hyperparameters also selected globally. Audit truth never fit or tuned.','leakage_checks':{'train_only':mid!='S5','condition_inference':False,'episode_grouped':True,'audit_fit':False,'same_cutoff_features':False},'dependencies':'numpy/scipy/sklearn','time_cap_seconds':600}
 if mid=='S5':extra['non_nested_stack_caveat']='S5 learner OOF folds differ from harness blend folds. Non-nested meta-weight fitting permits indirect validation-q information; separate nested outer/inner episode diagnostic required.'
 if mid=='S6':extra['future_drift_bias']='Future-window32 target can average across drift; sparse windows require at least4 observations.'
 doc=write_result(mid,'codex',{'S2':'CatBoost and LightGBM residual on B3','S1':'HistGB residual on B3','S3':'train-condition classifier gating residual specialists','S4':'rolling train pseudo-cutoff residual ridge','S5':'dev episode-OOF true-q distillation','S6':'train future-window soft-target residual ridge','S7':'full-feature multinomial logistic','S8':'deterministic small residual MLP'}[mid],dict(config=CONFIGS[idx],hyper=h,training_iterations=HIST_ITER if mid=='S1' else MLP_ITER if mid=='S8' else None),v,p,time.monotonic()-start,SEED,False,det,extra=extra)
 to_csv('results/preds/'+mid+'_validation.csv',v,p)
 lines=[mid, 'Completed grid cells: '+str(len(cells))+'/'+str(128 if mid=='S2' else 64)+'; feature ablations: '+str(len(abl)), 'Best params: '+json.dumps(doc['params']), 'Points/CI95: '+json.dumps([doc['points'],doc['ci95']]), 'Condition ratios: '+json.dumps(doc['condition_ratios']), 'Class shares: '+json.dumps(doc['class_error_shares']), 'Standalone paired B3: '+json.dumps(paired), 'Episode-OOF blend: '+json.dumps(blend), 'Runtime seconds: '+str(doc['runtime_seconds']), 'Determinism max diff: '+str(det), 'stdlib-only: no', 'Audit excluded from fitting/tuning; condition labels never used at inference.', extra['selection_caveat']]
 if mid=='S5':lines.append(extra['non_nested_stack_caveat'])
 if mid=='S6':lines.append(extra['future_drift_bias'])
 if mid=='S2' and any(not z['available'] for z in optional_status.values()):lines.append('Optional runtime attempts: '+json.dumps(optional_status))
 Path('reports/'+mid+'.md').write_text('\n'.join(lines)+'\n');print(json.dumps({'id':mid,'points':pts,'completed_cells':len(cells),'runtime_seconds':doc['runtime_seconds']}))
if __name__=='__main__':main()
